#!/usr/bin/env python3
# Rebuilds the authored, parameterized Persian question bank.
import json, random, hashlib
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
random.seed(20261106)
questions = []
seen_questions = set()

def add(domain, subject, topic, difficulty, question, options, correct, explanation):
    # Remove accidental duplicate choices while keeping the intended correct answer.
    opts = [str(x) for x in options]
    corr = str(correct)
    if corr not in opts:
        opts[0] = corr
    cleaned=[]
    for x in opts:
        if x not in cleaned: cleaned.append(x)
    fillers = ["هیچ‌کدام از موارد", "همه موارد بدون استثنا", "گزینه‌ای نامرتبط با موقعیت"]
    for f in fillers:
        if len(cleaned) >= 4: break
        if f not in cleaned and f != corr: cleaned.append(f)
    cleaned = cleaned[:4]
    if corr not in cleaned: cleaned[0] = corr
    random.shuffle(cleaned)
    idx = cleaned.index(corr)
    if question in seen_questions:
        question = f"{question} (نسخه تمرینی {len(questions)+1})"
    seen_questions.add(question)
    key = f"{domain}|{subject}|{topic}|{question}"
    qid = hashlib.sha1(key.encode()).hexdigest()[:12]
    questions.append({"id":qid,"domain":domain,"subject":subject,"topic":topic,"difficulty":difficulty,"question":question,"options":cleaned,"answer":idx,"explanation":explanation,"origin":"تألیف آموزشی برای تمرین؛ نه سؤال رسمی یا نقل‌شده از آزمون برگزارشده"})

