punctuation=[("امروز هوا آفتابی است", ".", "جمله خبری"),("آیا کتابت را خواندی", "؟", "جمله پرسشی"),("چه منظره زیبایی", "!", "جمله عاطفی"),("مداد، دفتر و پاک‌کن خریدم", ".", "پایان جمله خبری"),("لطفاً آرام‌تر صحبت کن", ".", "جمله درخواستی"),("چه کسی زنگ زد", "؟", "پرسش"),("آفرین، پاسخ درستی دادی", "!", "تعجب و تشویق"),("من سیب، گلابی و پرتقال دوست دارم", ".", "پایان جمله"),("کجا زندگی می‌کنی", "؟", "پرسش"),("مواظب باش", "!", "هشدار"),("باران شروع شد", ".", "خبر"),("چرا دیر رسیدی", "؟", "پرسش"),("چه روز دل‌انگیزی", "!", "عاطفه"),("دانش‌آموزان وارد کلاس شدند", ".", "خبر"),("آیا آماده‌ای", "؟", "پرسش"),("آه، چه اتفاقی", "!", "عاطفه"),("امروز کتاب می‌خوانیم", ".", "خبر"),("کدام مسیر کوتاه‌تر است", "؟", "پرسش"),("به‌به، چه خط زیبایی", "!", "تشویق"),("قطار به ایستگاه رسید", ".", "خبر"),("نام تو چیست", "؟", "پرسش"),("چه صدای بلندی", "!", "عاطفه"),("پرنده روی شاخه نشست", ".", "خبر"),("چند نفر در گروه هستند", "؟", "پرسش"),("آفرین بر تلاش تو", "!", "تشویق")]
