subjects=[("پرندگان در آسمان پرواز می‌کنند","پرندگان"),("مادر غذای خوشمزه‌ای پخت","مادر"),("دانش‌آموزان با دقت گوش می‌دهند","دانش‌آموزان"),("باران آرام می‌بارد","باران"),("درختان در بهار شکوفه می‌دهند","درختان"),("قطار به ایستگاه رسید","قطار"),("معلم درس را توضیح داد","معلم"),("کودک خندید","کودک"),("خورشید از پشت ابر بیرون آمد","خورشید"),("ماهی در آب شنا می‌کند","ماهی"),("کشاورز زمین را شخم زد","کشاورز"),("زنبورها شهد گل‌ها را جمع می‌کنند","زنبورها"),("ورزشکاران تمرین کردند","ورزشکاران"),("کتاب روی میز قرار دارد","کتاب"),("پروانه روی گل نشست","پروانه"),("دوستانم به خانه آمدند","دوستانم"),("باد شاخه‌ها را تکان داد","باد"),("نویسنده داستانی نوشت","نویسنده"),("دانش‌آموز پاسخ را یافت","دانش‌آموز"),("ماه در آسمان می‌درخشد","ماه"),("باغبان گل‌ها را آبیاری کرد","باغبان"),("مردم به پارک رفتند","مردم"),("ساعت دیواری زنگ زد","ساعت دیواری"),("ابرها آسمان را پوشاندند","ابرها"),("پزشک بیمار را معاینه کرد","پزشک")]
