verbs=[("نوشت","گذشته"),("می‌خواند","حال"),("خواهد رفت","آینده"),("بخور","امر"),("دیدند","گذشته"),("می‌سازیم","حال"),("خواهی آمد","آینده"),("بنشین","امر"),("گفت","گذشته"),("می‌دود","حال"),("خواهند نوشت","آینده"),("بخوانید","امر"),("خوابیدم","گذشته"),("می‌بارد","حال"),("خواهیم دید","آینده"),("بنویس","امر"),("رسیدند","گذشته"),("می‌خندد","حال"),("خواهد ساخت","آینده"),("گوش کنید","امر"),("پخت","گذشته"),("می‌تابد","حال"),("خواهند رسید","آینده"),("باز کن","امر"),("آموختیم","گذشته")]
