adjectives=[("گل سرخ","سرخ"),("آسمان آبی","آبی"),("کتاب مفید","مفید"),("کودک مهربان","مهربان"),("هوای سرد","سرد"),("خانه بزرگ","بزرگ"),("دوست صمیمی","صمیمی"),("آب زلال","زلال"),("پرنده کوچک","کوچک"),("راه باریک","باریک"),("مرد دانا","دانا"),("غذای گرم","گرم"),("دریای آرام","آرام"),("لباس تمیز","تمیز"),("درخت بلند","بلند"),("صدای آهسته","آهسته"),("دانش‌آموز کوشا","کوشا"),("شب تاریک","تاریک"),("میوه شیرین","شیرین"),("دیوار سفید","سفید"),("باغ سرسبز","سرسبز"),("روز آفتابی","آفتابی"),("دفتر نو","نو"),("مردم صبور","صبور"),("جاده طولانی","طولانی")]
