for topic,stems,opts,correct,explain in quran_families:
    for i in range(25):
        q=stems[i%len(stems)]
        settings=["در خانه","در مدرسه","در محله","در جمع دوستان","در یک موقعیت روزمره"]
        add("elementary","قرآن و هدیه‌های آسمان",topic,"آسان" if i%2==0 else "متوسط",f"{settings[i//5]}، {q} (تمرین {i+1})",opts,correct,f"{explain} پاسخ درست: {correct}.")

# ---------------- IQ mathematics: exactly 200 ----------------
# sequences: arithmetic and geometric
for i in range(30):
    start=1+(i%12); step=2+(i%7); seq=[start+j*step for j in range(4)]; ans=seq[-1]+step
    add("iq","هوش ریاضی","دنباله عددی","متوسط" if i%2 else "آسان",f"عدد بعدی دنباله {', '.join(map(str,seq))} کدام است؟",[str(ans),str(ans+step),str(ans-step),str(ans+1)],str(ans),f"اختلاف جمله‌های پیاپی {step} است؛ بنابراین {seq[-1]}+{step}={ans}.")
for i in range(20):
    base=2+(i%3); start=1+(i%4); seq=[start*(base**j) for j in range(4)]; ans=seq[-1]*base
    add("iq","هوش ریاضی","الگوی ضربی","دشوار",f"الگوی {', '.join(map(str,seq))} را ادامه دهید.",[str(ans),str(ans+base),str(ans//base),str(ans+1)],str(ans),f"هر جمله {base} برابر جمله پیشین است؛ {seq[-1]}×{base}={ans}.")
for i in range(20):
    a=2+i%9; b=3+(i*2)%8; c=1+(i%5); ans=a*b+c
    add("iq","هوش ریاضی","ترتیب عملیات","متوسط",f"با رعایت تقدم ضرب بر جمع، مقدار {a}×{b}+{c} چند می‌شود؟",[str(ans),str(a*(b+c)),str(ans+1),str(ans-2)],str(ans),f"ابتدا ضرب: {a}×{b}={a*b}؛ سپس جمع: {a*b}+{c}={ans}.")
for i in range(20):
    total=24+i*3; groups=3+(i%6); per=total//groups
    total=per*groups
    add("iq","هوش ریاضی","تقسیم و تناسب","متوسط",f"{total} شیء را به‌طور مساوی میان {groups} نفر تقسیم کنیم، سهم هر نفر چند است؟",[str(per),str(per+1),str(groups),str(total-groups)],str(per),f"{total}÷{groups}={per}؛ پس سهم هر نفر {per} است.")
for i in range(20):
    den=2+(i%8); n=1+(i%(den-1)); m=den-n
    # compare n/den with 1/2 using cross multiplication
    correct="بزرگ‌تر از نصف" if 2*n>den else ("برابر نصف" if 2*n==den else "کوچک‌تر از نصف")
    add("iq","هوش ریاضی","کسر و مقایسه","دشوار",f"کسر {n}/{den} نسبت به یک‌دوم چه وضعیتی دارد؟",[correct,"همیشه برابر یک‌دوم است","همیشه بزرگ‌تر از یک‌دوم است","قابل مقایسه نیست"],correct,f"برای مقایسه {n}/{den} با ۱/۲، صورت را در ۲ ضرب می‌کنیم: {2*n} {'>' if 2*n>den else ('=' if 2*n==den else '<')} {den}؛ پس کسر {correct}.")
for i in range(20):
    length=3+i%11; width=2+(i*2)%9; answer=length*width
    add("iq","هوش ریاضی","هندسه و مساحت","متوسط",f"کف اتاقی مستطیلی به طول {length} و عرض {width} متر است. مساحت آن چند متر مربع است؟",[str(answer),str(2*(length+width)),str(length+width),str(answer+length)],str(answer),f"مساحت مستطیل = طول × عرض = {length}×{width}={answer} متر مربع.")
for i in range(15):
    h=1+i%4; m=10+(i*7)%50; total=h*60+m
    add("iq","هوش ریاضی","زمان و ساعت","متوسط",f"{h} ساعت و {m} دقیقه چند دقیقه است؟",[str(total),str(h+m),str(total+60),str(h*100+m)],str(total),f"هر ساعت ۶۰ دقیقه است: {h}×۶۰+{m}={total} دقیقه.")
