# Split for easier caching and future extension
for filename, subset in [
    ("professional.json", [q for q in questions if q['domain']=='professional']),
    ("elementary.json", [q for q in questions if q['domain']=='elementary']),
    ("iq-math.json", [q for q in questions if q['domain']=='iq'])]:
    (ROOT/"data"/filename).write_text(json.dumps(subset,ensure_ascii=False,indent=2),encoding='utf-8')
